From 4e65a8b8daa18d63255ec58964dd192c7fdd9f8b Mon Sep 17 00:00:00 2001
From: Eric Dumazet <edumazet@google.com>
Date: Thu, 2 Apr 2026 10:17:32 +0000
Subject: [PATCH] ipv6: ioam: fix potential NULL dereferences in
 __ioam6_fill_trace_data()

We need to check __in6_dev_get() for possible NULL value, as
suggested by Yiming Qian.

Also add skb_dst_dev_rcu() instead of skb_dst_dev(),
and two missing READ_ONCE().

Note that @dev can't be NULL.

Fixes: 9ee11f0fff20 ("ipv6: ioam: Data plane support for Pre-allocated Trace")
Reported-by: Yiming Qian <yimingqian591@gmail.com>
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reviewed-by: Justin Iurman <justin.iurman@gmail.com>
Link: https://patch.msgid.link/20260402101732.1188059-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

diff --git a/net/ipv6/ioam6.c b/net/ipv6/ioam6.c
index 3978773bec42..05a0b7d7e2aa 100644
--- a/net/ipv6/ioam6.c
+++ b/net/ipv6/ioam6.c
@@ -710,7 +710,9 @@ static void __ioam6_fill_trace_data(struct sk_buff *skb,
 				    struct ioam6_schema *sc,
 				    unsigned int sclen, bool is_input)
 {
-	struct net_device *dev = skb_dst_dev(skb);
+	/* Note: skb_dst_dev_rcu() can't be NULL at this point. */
+	struct net_device *dev = skb_dst_dev_rcu(skb);
+	struct inet6_dev *i_skb_dev, *idev;
 	struct timespec64 ts;
 	ktime_t tstamp;
 	u64 raw64;
@@ -721,13 +723,16 @@ static void __ioam6_fill_trace_data(struct sk_buff *skb,

 	data = trace->data + trace->remlen * 4 - trace->nodelen * 4 - sclen * 4;

+	i_skb_dev = skb->dev ? __in6_dev_get(skb->dev) : NULL;
+	idev = __in6_dev_get(dev);
+
 	/* hop_lim and node_id */
 	if (trace->type.bit0) {
 		byte = ipv6_hdr(skb)->hop_limit;
 		if (is_input)
 			byte--;

-		raw32 = dev_net(dev)->ipv6.sysctl.ioam6_id;
+		raw32 = READ_ONCE(dev_net(dev)->ipv6.sysctl.ioam6_id);

 		*(__be32 *)data = cpu_to_be32((byte << 24) | raw32);
 		data += sizeof(__be32);
@@ -735,18 +740,18 @@ static void __ioam6_fill_trace_data(struct sk_buff *skb,

 	/* ingress_if_id and egress_if_id */
 	if (trace->type.bit1) {
-		if (!skb->dev)
+		if (!i_skb_dev)
 			raw16 = IOAM6_U16_UNAVAILABLE;
 		else
-			raw16 = (__force u16)READ_ONCE(__in6_dev_get(skb->dev)->cnf.ioam6_id);
+			raw16 = (__force u16)READ_ONCE(i_skb_dev->cnf.ioam6_id);

 		*(__be16 *)data = cpu_to_be16(raw16);
 		data += sizeof(__be16);

-		if (dev->flags & IFF_LOOPBACK)
+		if ((dev->flags & IFF_LOOPBACK) || !idev)
 			raw16 = IOAM6_U16_UNAVAILABLE;
 		else
-			raw16 = (__force u16)READ_ONCE(__in6_dev_get(dev)->cnf.ioam6_id);
+			raw16 = (__force u16)READ_ONCE(idev->cnf.ioam6_id);

 		*(__be16 *)data = cpu_to_be16(raw16);
 		data += sizeof(__be16);
@@ -822,7 +827,7 @@ static void __ioam6_fill_trace_data(struct sk_buff *skb,
 		if (is_input)
 			byte--;

-		raw64 = dev_net(dev)->ipv6.sysctl.ioam6_id_wide;
+		raw64 = READ_ONCE(dev_net(dev)->ipv6.sysctl.ioam6_id_wide);

 		*(__be64 *)data = cpu_to_be64(((u64)byte << 56) | raw64);
 		data += sizeof(__be64);
@@ -830,18 +835,18 @@ static void __ioam6_fill_trace_data(struct sk_buff *skb,

 	/* ingress_if_id and egress_if_id (wide) */
 	if (trace->type.bit9) {
-		if (!skb->dev)
+		if (!i_skb_dev)
 			raw32 = IOAM6_U32_UNAVAILABLE;
 		else
-			raw32 = READ_ONCE(__in6_dev_get(skb->dev)->cnf.ioam6_id_wide);
+			raw32 = READ_ONCE(i_skb_dev->cnf.ioam6_id_wide);

 		*(__be32 *)data = cpu_to_be32(raw32);
 		data += sizeof(__be32);

-		if (dev->flags & IFF_LOOPBACK)
+		if ((dev->flags & IFF_LOOPBACK) || !idev)
 			raw32 = IOAM6_U32_UNAVAILABLE;
 		else
-			raw32 = READ_ONCE(__in6_dev_get(dev)->cnf.ioam6_id_wide);
+			raw32 = READ_ONCE(idev->cnf.ioam6_id_wide);

 		*(__be32 *)data = cpu_to_be32(raw32);
 		data += sizeof(__be32);
-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ipv6: ioam: fix potential NULL dereferences in
 __ioam6_fill_trace_data()

We need to check __in6_dev_get() for possible NULL value, as
suggested by Yiming Qian.

Also add skb_dst_dev_rcu() instead of skb_dst_dev(),
and two missing READ_ONCE().

Note that @dev can't be NULL.

Fixes: 9ee11f0fff20 ("ipv6: ioam: Data plane support for Pre-allocated Trace")
Reported-by: Yiming Qian <yimingqian591@gmail.com>
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reviewed-by: Justin Iurman <justin.iurman@gmail.com>
Link: https://patch.msgid.link/20260402101732.1188059-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function `__ioam6_fill_trace_data()` in `net/ipv6/ioam6.c` calls `__in6_dev_get()` without checking its return value for NULL. When the device does not have an IPv6 `inet6_dev` structure (e.g., non-IPv6 interfaces or transient states), `__in6_dev_get()` returns NULL, leading to a potential NULL pointer dereference when accessing `cnf.ioam6_id` or `cnf.ioam6_id_wide`.

Here is the patch:

 static void __ioam6_fill_trace_data(struct sk_buff *skb,
 				    struct ioam6_namespace *ns,
 				    struct ioam6_trace_hdr *trace,
 				    struct ioam6_schema *sc,
 				    unsigned int sclen, bool is_input)
 {
-	struct net_device *dev = skb_dst_dev(skb);
+	/* Note: skb_dst_dev_rcu() can't be NULL at this point. */
+	struct net_device *dev = skb_dst_dev_rcu(skb);
+	struct inet6_dev *i_skb_dev, *idev;
 	struct timespec64 ts;
 	ktime_t tstamp;
 	u64 raw64;
 	u32 raw32;
 	u16 raw16;
 	u8 *data;
 	u8 byte;

 	data = trace->data + trace->remlen * 4 - trace->nodelen * 4 - sclen * 4;

+	i_skb_dev = skb->dev ? __in6_dev_get(skb->dev) : NULL;
+	idev = __in6_dev_get(dev);
+
 	/* hop_lim and node_id */
 	if (trace->type.bit0) {
 		byte = ipv6_hdr(skb)->hop_limit;
 		if (is_input)
 			byte--;

-		raw32 = dev_net(dev)->ipv6.sysctl.ioam6_id;
+		raw32 = READ_ONCE(dev_net(dev)->ipv6.sysctl.ioam6_id);

 		*(__be32 *)data = cpu_to_be32((byte << 24) | raw32);
 		data += sizeof(__be32);
 	}

 	/* ingress_if_id and egress_if_id */
 	if (trace->type.bit1) {
-		if (!skb->dev)
+		if (!i_skb_dev)
 			raw16 = IOAM6_U16_UNAVAILABLE;
 		else
-			raw16 = (__force u16)READ_ONCE(__in6_dev_get(skb->dev)->cnf.ioam6_id);
+			raw16 = (__force u16)READ_ONCE(i_skb_dev->cnf.ioam6_id);

 		*(__be16 *)data = cpu_to_be16(raw16);
 		data += sizeof(__be16);

-		if (dev->flags & IFF_LOOPBACK)
+		if ((dev->flags & IFF_LOOPBACK) || !idev)
 			raw16 = IOAM6_U16_UNAVAILABLE;
 		else
-			raw16 = (__force u16)READ_ONCE(__in6_dev_get(dev)->cnf.ioam6_id);
+			raw16 = (__force u16)READ_ONCE(idev->cnf.ioam6_id);

 		*(__be16 *)data = cpu_to_be16(raw16);
 		data += sizeof(__be16);
 	}

 	/* timestamp seconds */
 	if (trace->type.bit2) {
 		if (!skb->dev) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		} else {
 			tstamp = skb_tstamp_cond(skb, true);
 			ts = ktime_to_timespec64(tstamp);

 			*(__be32 *)data = cpu_to_be32((u32)ts.tv_sec);
 		}
 		data += sizeof(__be32);
 	}

 	/* timestamp subseconds */
 	if (trace->type.bit3) {
 		if (!skb->dev) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		} else {
 			if (!trace->type.bit2) {
 				tstamp = skb_tstamp_cond(skb, true);
 				ts = ktime_to_timespec64(tstamp);
 			}

 			*(__be32 *)data = cpu_to_be32((u32)(ts.tv_nsec / NSEC_PER_USEC));
 		}
 		data += sizeof(__be32);
 	}

 	/* transit delay */
 	if (trace->type.bit4) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* namespace data */
 	if (trace->type.bit5) {
 		*(__be32 *)data = ns->data;
 		data += sizeof(__be32);
 	}

 	/* queue depth */
 	if (trace->type.bit6) {
 		struct netdev_queue *queue;
 		struct Qdisc *qdisc;
 		__u32 qlen, backlog;

 		if (dev->flags & IFF_LOOPBACK) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		} else {
 			queue = skb_get_tx_queue(dev, skb);
 			qdisc = rcu_dereference(queue->qdisc);
 			qdisc_qstats_qlen_backlog(qdisc, &qlen, &backlog);

 			*(__be32 *)data = cpu_to_be32(backlog);
 		}
 		data += sizeof(__be32);
 	}

 	/* checksum complement */
 	if (trace->type.bit7) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* hop_lim and node_id (wide) */
 	if (trace->type.bit8) {
 		byte = ipv6_hdr(skb)->hop_limit;
 		if (is_input)
 			byte--;

-		raw64 = dev_net(dev)->ipv6.sysctl.ioam6_id_wide;
+		raw64 = READ_ONCE(dev_net(dev)->ipv6.sysctl.ioam6_id_wide);

 		*(__be64 *)data = cpu_to_be64(((u64)byte << 56) | raw64);
 		data += sizeof(__be64);
 	}

 	/* ingress_if_id and egress_if_id (wide) */
 	if (trace->type.bit9) {
-		if (!skb->dev)
+		if (!i_skb_dev)
 			raw32 = IOAM6_U32_UNAVAILABLE;
 		else
-			raw32 = READ_ONCE(__in6_dev_get(skb->dev)->cnf.ioam6_id_wide);
+			raw32 = READ_ONCE(i_skb_dev->cnf.ioam6_id_wide);

 		*(__be32 *)data = cpu_to_be32(raw32);
 		data += sizeof(__be32);

-		if (dev->flags & IFF_LOOPBACK)
+		if ((dev->flags & IFF_LOOPBACK) || !idev)
 			raw32 = IOAM6_U32_UNAVAILABLE;
 		else
-			raw32 = READ_ONCE(__in6_dev_get(dev)->cnf.ioam6_id_wide);
+			raw32 = READ_ONCE(idev->cnf.ioam6_id_wide);

 		*(__be32 *)data = cpu_to_be32(raw32);
 		data += sizeof(__be32);
 	}

 	/* namespace data (wide) */
 	if (trace->type.bit10) {
 		*(__be64 *)data = ns->data_wide;
 		data += sizeof(__be64);
 	}

 	/* buffer occupancy */
 	if (trace->type.bit11) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit12 undefined: filled with empty value */
 	if (trace->type.bit12) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit13 undefined: filled with empty value */
 	if (trace->type.bit13) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit14 undefined: filled with empty value */
 	if (trace->type.bit14) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit15 undefined: filled with empty value */
 	if (trace->type.bit15) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit16 undefined: filled with empty value */
 	if (trace->type.bit16) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit17 undefined: filled with empty value */
 	if (trace->type.bit17) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit18 undefined: filled with empty value */
 	if (trace->type.bit18) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit19 undefined: filled with empty value */
 	if (trace->type.bit19) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit20 undefined: filled with empty value */
 	if (trace->type.bit20) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* bit21 undefined: filled with empty value */
 	if (trace->type.bit21) {
 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* opaque state snapshot */
 	if (trace->type.bit22) {
 		if (!sc) {
 			*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE >> 8);
 		} else {
 			*(__be32 *)data = sc->hdr;
 			data += sizeof(__be32);

 			memcpy(data, sc->data, sc->len);
 		}
 	}
 }



